// WithEnv: builds the executor now, possibly before the logger option ran.
func WithEnv(env []string) ProvisionerOption {
    return func(p *Provisioner) {
        if p.executor == nil {
            p.executor = executor.New(executor.WithEnv(env))
        } else {
            p.executor.Env = append(p.executor.Env, env...)
        }
    }
}

// New: compensates after the loop.
// WithEnv may have constructed the executor before WithLogger was applied;
// ensure the final logger is attached either way.
executor.WithLogger(p.logger)(p.executor)

func (p *Phase) SetupKubeconfig(clusterDir string) error {
    kubeconfigPath := filepath.Join(clusterDir, "auth", "kubeconfig")
    if !system.FileExists(kubeconfigPath) {
        return fmt.Errorf("kubeconfig not found at %s", kubeconfigPath)
    }
    p.Exec.Env = append(p.Exec.Env, "KUBECONFIG="+kubeconfigPath)
    ...
}

